extends RefCounted
## A GDScript navigation-mesh builder and query engine over `Geometry2D`.

## Public state (rebuilt on every call to `build(...)`)
var _triangles: Array = []        ## Array[PackedVector2Array], each 3 vertices.
var _centroids: Array = []       ## Array[Vector2], triangle centroids.
var _adjacency: Array = []       ## Array[PackedInt32Array], neighbors sorted ascending.
var _astar: AStar2D = null       ## AStar2D graph of triangle centroids.

## Configuration
const MIN_TRIANGLE_AREA := 1e-6
const VERTEX_EQUALS_EPSILON := 1e-5

## -----------------------------------------------------------------------------
## Public API
## -----------------------------------------------------------------------------


func build(boundary: PackedVector2Array, holes: Array) -> void:
	"""Build a NavigationMesh: `boundary` interior minus all `holes` interiors.

	Boundary and holes may be given in either winding order; both are
	normalized. Holes are excluded regardless of their original winding. Each
	call fully replaces the query-method state.
	"""
	_reset()

	if boundary.size() < 3:
		return

	# Normalize orientations: exterior = Counter-Clockwise (interior on left),
	# each hole = Clockwise (interior on right, to be cut out).
	var combined := _ensure_ccw(boundary)

	var safe_holes := []
	if holes != null:
		safe_holes = holes

	# Cut every hole into the boundary with a zero-width "bridge" edge, turning
	# the hole-with-voids into a single simple polygon suitable for
	# `triangulate_polygon`. A bridge is a coincident edge pair entering the
	# hole from the nearest boundary vertex and returning along itself.
	for hole in safe_holes:
		if hole is PackedVector2Array and hole.size() >= 3:
			combined = _add_hole(combined, hole)

	# Triangulate the resulting hole-pierced polygon. The winding ensures the
	# walkable interior is what gets filled with triangles.
	var vertex_blob := Geometry2D.triangulate_polygon(combined)
	if vertex_blob.size() % 3 != 0:
		return

	var raw := []
	for i in range(0, vertex_blob.size(), 3):
		raw.append(PackedVector2Array([
			vertex_blob[i],
			vertex_blob[i + 1],
			vertex_blob[i + 2],
		]))

	# Keep only non-degenerate triangles (area > 0). The bridge edges create
	# thin/collinear triangles that are invalid navigation surfaces.
	for tri in raw:
		if _triangle_area(tri) > MIN_TRIANGLE_AREA:
			_triangles.append(tri)
			_centroids.append(_triangle_centroid(tri))

	_build_adjacency()
	_build_graph()


func get_triangles() -> Array:
	"""Return Array[PackedVector2Array], each exactly 3 vertices. Index = t."""
	return _triangles


func get_adjacency() -> Array:
	"""Return Array[PackedInt32Array], element t = sorted neighbor indices."""
	return _adjacency


func triangle_at_point(point: Vector2) -> int:
	"""Find the triangle containing `point`, or -1 (outside boundary or in hole)."""
	for i in range(_triangles.size()):
		# Point is inside or on the edge of a non-degenerate triangle -> walkable.
		# Holes are not covered, and points outside the boundary are not covered.
		if Geometry2D.point_in_polygon(point, _triangles[i]) != -1:
			return i
	return -1


func find_triangle_path(from_point: Vector2, to_point: Vector2) -> PackedInt32Array:
	"""Triangle-level path from `from_point` to `to_point` via centroid AStar.

	- Returns `[triangle_at_point(from_point), ..., triangle_at_point(to_point)]`.
	- Every adjacent pair is connected; empty PackedInt32Array on failure.
	- Same endpoint resolves to the single index; off-mesh/disconnected -> empty.
	"""
	var start_idx := triangle_at_point(from_point)
	var end_idx := triangle_at_point(to_point)

	if start_idx == -1 or end_idx == -1:
		return PackedInt32Array()

	if start_idx == end_idx:
		return PackedInt32Array([start_idx])

	if _astar == null or not _astar.has_point(start_idx) or not _astar.has_point(end_idx):
		return PackedInt32Array()

	var path := _astar.get_id_path(start_idx, end_idx)
	return path if path != null else PackedInt32Array()


## -----------------------------------------------------------------------------
## Internals
## -----------------------------------------------------------------------------


func _reset() -> void:
	_triangles = []
	_centroids = []
	_adjacency = []
	if _astar != null:
		_astar.clear()
		_astar = null


func _build_adjacency() -> void:
	var n := _triangles.size()
	_adjacency = []
	_adjacency.resize(n)

	for i in range(n):
		_adjacency[i] = PackedInt32Array()

	for i in range(n):
		var ti := _triangles[i]
		for j in range(i + 1, n):
			if _triangles_share_edge(ti, _triangles[j]):
				_adjacency[i].append(j)
				_adjacency[j].append(i)

	for i in range(n):
		_adjacency[i].sort()


func _build_graph() -> void:
	_astar = AStar2D.new()
	var n := _triangles.size()
	for i in range(n):
		_astar.add_point(i, _centroids[i])

	for i in range(n):
		for neighbor in _adjacency[i]:
			if neighbor > i:
				_astar.connect_points(i, neighbor)


func _add_hole(poly: PackedVector2Array, hole: PackedVector2Array) -> PackedVector2Array:
	# Normalize the hole to Clockwise (interior on the right).
	var cw_hole := _ensure_cw(hole)

	# Find the closest pair of vertices (b on exterior, h on hole) to bridge the
	# void. This pair defines the zero-width cut connecting them.
	var b_idx := 0
	var h_idx := 0
	var min_sq := INF
	for i in range(poly.size()):
		var pb := poly[i]
		for j in range(cw_hole.size()):
			var ph := cw_hole[j]
			var d2 := pb.distance_squared_to(ph)
			if d2 < min_sq:
				min_sq = d2
				b_idx = i
				h_idx = j

	var b := poly[b_idx]
	var h := cw_hole[h_idx]

	# Build the single polygon with the bridge spliced in:
	#   ... poly[b_idx], (bridge out b->h), hole ... h (bridge in h->b), poly[b_idx+1] ...
	var segment := [h]
	# Walk the hole once, starting from the vertex after h and wrapping around.
	for i in range(1, cw_hole.size() + 1):
		segment.append(cw_hole[(h_idx + i) % cw_hole.size()])
	# Return back to the bridge-entry point.
	segment.append(h)

	var result := PackedVector2Array()
	# The original exterior up to and including the bridge-entry point `b`.
	for i in range(b_idx + 1):
		result.append(poly[i])
	# Splice in the hole-with-voids.
	for pt in segment:
		result.append(pt)
	# The rest of the original exterior.
	for i in range(b_idx + 1, poly.size()):
		result.append(poly[i])

	return result


func _triangles_share_edge(ta: PackedVector2Array, tb: PackedVector2Array) -> bool:
	# Two triangles are adjacent iff they share exactly two vertices at the
	# same position.
	var shared := 0
	for i in range(3):
		for j in range(3):
			if ta[i].distance_to(tb[j]) < VERTEX_EQUALS_EPSILON:
				shared += 1
				break
	return shared == 2


func _triangle_area(t: PackedVector2Array) -> float:
	return 0.5 * absf(
		t[0].x * (t[1].y - t[2].y) +
		t[1].x * (t[2].y - t[0].y) +
		t[2].x * (t[0].y - t[1].y)
	)


func _triangle_centroid(t: PackedVector2Array) -> Vector2:
	return (t[0] + t[1] + t[2]) / 3.0


func _ensure_ccw(poly: PackedVector2Array) -> PackedVector2Array:
	var copy := poly.duplicate()
	if Geometry2D.is_polygon_clockwise(copy):
		copy.reverse()
	return copy


func _ensure_cw(poly: PackedVector2Array) -> PackedVector2Array:
	var copy := poly.duplicate()
	if not Geometry2D.is_polygon_clockwise(copy):
		copy.reverse()
	return copy

